"""Shared internals: handle coercion and Win32 error classification.

Kept separate from :mod:`wspawn.errors` so that the public error type stays a
plain exception class, and separate from :mod:`wspawn._winapi` so that the
ctypes layer never has to know about :class:`WSpawnError`.
"""

from . import _winapi
from .errors import WSpawnError


def coerce_handle(handle, what="handle"):
    """Return ``handle`` as a Win32 ``HANDLE`` value (a plain integer).

    Accepts an integer handle, or any object exposing ``fileno()`` -- the
    descriptor of such an object is translated to the underlying Win32 handle,
    because the handover contract is defined on handles, not on descriptors.
    """
    if isinstance(handle, bool):
        raise WSpawnError(
            "%s must be an object handle, got %r" % (what, handle), kind="badarg"
        )
    if isinstance(handle, int):
        return int(handle)

    fileno = getattr(handle, "fileno", None)
    if callable(fileno):
        if not _winapi.is_windows():
            raise WSpawnError(
                "translating a file object to an object handle needs Windows",
                kind="unsupported",
            )
        try:
            import msvcrt

            return int(msvcrt.get_osfhandle(fileno()))
        except (OSError, ValueError) as exc:
            raise WSpawnError(
                "%s does not have a usable object handle: %s" % (what, exc),
                kind="badarg",
            ) from exc

    raise WSpawnError(
        "%s must be an object handle, got %r" % (what, handle), kind="badarg"
    )


def require_windows(operation):
    """Raise ``unsupported`` unless the precise handover primitives exist.

    ``wspawn`` hands over Win32 objects by name; there is no second mechanism
    that offers the same guarantee, so an environment without the Win32 handle
    APIs is reported rather than silently approximated.
    """
    if not _winapi.is_windows():
        raise WSpawnError(
            "%s requires Windows object-handle semantics; this runtime does not "
            "provide them" % operation,
            kind="unsupported",
        )


def os_error(exc, message, handle=None):
    """Translate an :class:`OSError` from a Win32 call into a ``WSpawnError``."""
    code = getattr(exc, "winerror", None)
    if code is None:
        code = getattr(exc, "errno", None)
    kind = "unsupported" if code in _winapi.UNSUPPORTED_ERRORS else "os"
    return WSpawnError("%s: %s" % (message, exc), kind=kind, handle=handle)

"""Starting helper processes with a handover of the caller's objects.

The handover is exact.  Windows decides what a child inherits from the
``PROC_THREAD_ATTRIBUTE_HANDLE_LIST`` process-creation attribute: when that
attribute is present, the child receives *only* the handles it names, even
though other handles in the parent are marked inheritable.  Each inherited
handle keeps its numeric value in the child, which is what lets the caller
hand the helper a handle value and have the helper use it directly.

Standard streams are a separate decision from the handover list: a stream the
caller did not name is pointed at ``NUL`` rather than at whatever the host had
open, so an unspecified stream can never become an accidental handover.
"""

import os
import subprocess

from . import _winapi
from ._common import coerce_handle, os_error, require_windows
from .errors import WSpawnError

_STD_SENTINELS = (subprocess.PIPE, subprocess.STDOUT, subprocess.DEVNULL)


class SpawnedProcess(object):
    """A helper process started by :func:`spawn`."""

    def __init__(self, popen, inherit):
        self._popen = popen
        self.inherit = tuple(inherit)
        self.pid = popen.pid
        self.returncode = None

    @property
    def stdin(self):
        return self._popen.stdin

    @property
    def stdout(self):
        return self._popen.stdout

    @property
    def stderr(self):
        return self._popen.stderr

    def wait(self, timeout=None):
        self.returncode = self._popen.wait(timeout=timeout)
        return self.returncode

    def poll(self):
        self.returncode = self._popen.poll()
        return self.returncode

    def terminate(self):
        self._popen.terminate()

    def kill(self):
        self._popen.kill()


def _normalise_argv(argv):
    if isinstance(argv, (str, bytes)):
        raise WSpawnError("argv must be a sequence of arguments, not a single string", kind="badarg")
    try:
        items = [os.fspath(item) for item in argv]
    except TypeError as exc:
        raise WSpawnError("argv must be an iterable of paths: %s" % exc, kind="badarg") from exc
    if not items:
        raise WSpawnError("argv must not be empty", kind="badarg")
    return items


def _normalise_handles(inherit):
    """Return the handover list as unique integer handles, order preserved."""
    if inherit is None:
        return ()
    if isinstance(inherit, (int, bytes, str)):
        raise WSpawnError("inherit must be a sequence of handles, not a single handle", kind="badarg")
    try:
        items = list(inherit)
    except TypeError as exc:
        raise WSpawnError("inherit must be a sequence of handles: %s" % exc, kind="badarg") from exc

    ordered = []
    seen = set()
    for item in items:
        number = coerce_handle(item, what="every entry of inherit")
        if number not in seen:
            seen.add(number)
            ordered.append(number)
    return tuple(ordered)


def _check_handover(handles):
    """Reject a handover that Windows cannot carry out, rather than trimming it.

    A console handle whose low two bits are set is a legacy pseudo handle; it
    cannot appear in a handle list, and passing it would be silently dropped
    (or crash the child).  Such a request is reported instead.
    """
    for handle in handles:
        try:
            _winapi.get_handle_information(handle)
        except OSError as exc:
            raise os_error(exc, "cannot hand over this object", handle=handle) from exc
        if handle & 0x3 == 0x3:
            try:
                kind = _winapi.file_type(handle)
            except OSError:
                kind = _winapi.FILE_TYPE_UNKNOWN
            if kind & ~_winapi.FILE_TYPE_REMOTE == _winapi.FILE_TYPE_CHAR:
                raise WSpawnError(
                    "a legacy console pseudo handle cannot be handed to a child "
                    "process; open CONIN$/CONOUT$ instead",
                    kind="unsupported",
                    handle=handle,
                )


def _resolve_std(stream, name, temporary_fds):
    """Map a standard-stream argument onto something ``Popen`` understands.

    ``None`` becomes ``NUL``: a stream the caller did not name must not expose
    the host's own console, log file or pipe to the helper.
    """
    if stream is None:
        return subprocess.DEVNULL
    if isinstance(stream, bool):
        raise WSpawnError("%s must be a stream, a handle or None, got %r" % (name, stream),
                          kind="badarg")
    if isinstance(stream, int):
        if stream in _STD_SENTINELS:
            return stream
        if stream < 0:
            raise WSpawnError("%s is not a usable stream: %r" % (name, stream), kind="badarg")
        return _std_from_number(stream, name, temporary_fds)
    if callable(getattr(stream, "fileno", None)):
        return stream
    raise WSpawnError("%s must be a stream, a handle or None, got %r" % (name, stream),
                      kind="badarg")


def _std_from_number(number, name, temporary_fds):
    """Accept either a C runtime descriptor or a Win32 handle for a std stream."""
    import msvcrt

    try:
        msvcrt.get_osfhandle(number)
    except (OSError, ValueError):
        pass
    else:
        return number

    try:
        _winapi.get_handle_information(number)
    except OSError as exc:
        raise WSpawnError("%s is neither a descriptor nor an object handle: %r"
                          % (name, number), kind="badarg") from exc

    # A bare object handle: give ``Popen`` a descriptor onto a private
    # duplicate so the caller keeps ownership of the original.
    try:
        duplicate = _winapi.duplicate_handle(number, inheritable=False)
        descriptor = msvcrt.open_osfhandle(duplicate, os.O_BINARY)
    except OSError as exc:
        raise os_error(exc, "cannot use this object as %s" % name, handle=number) from exc
    temporary_fds.append(descriptor)
    return descriptor


def spawn(argv, inherit=(), stdin=None, stdout=None, stderr=None):
    """Start a helper process, handing it the objects named in ``inherit``.

    The helper can reach exactly the objects in ``inherit`` plus the standard
    streams named by ``stdin`` / ``stdout`` / ``stderr``; every other
    inheritable object of this process stays out of its reach.  Handles in
    ``inherit`` keep their numeric value inside the helper.

    Returns a :class:`SpawnedProcess`.
    """
    command = _normalise_argv(argv)
    handles = _normalise_handles(inherit)

    require_windows("handing selected objects to a child process")
    _check_handover(handles)

    startupinfo = subprocess.STARTUPINFO()
    startupinfo.lpAttributeList = {"handle_list": list(handles)}

    temporary_fds = []
    restore = []
    try:
        streams = {
            "stdin": _resolve_std(stdin, "stdin", temporary_fds),
            "stdout": _resolve_std(stdout, "stdout", temporary_fds),
            "stderr": _resolve_std(stderr, "stderr", temporary_fds),
        }

        # Every handle in a handle list has to be inheritable at the moment of
        # process creation, so flip the flag for the duration of the call and
        # put each object back exactly as the caller left it afterwards.
        for handle in handles:
            try:
                flags = _winapi.get_handle_information(handle)
            except OSError as exc:
                raise os_error(exc, "cannot hand over this object", handle=handle) from exc
            if not flags & _winapi.HANDLE_FLAG_INHERIT:
                try:
                    _winapi.set_handle_information(
                        handle, _winapi.HANDLE_FLAG_INHERIT, _winapi.HANDLE_FLAG_INHERIT
                    )
                except OSError as exc:
                    raise os_error(exc, "this object cannot be handed to a child process",
                                   handle=handle) from exc
                restore.append(handle)

        try:
            popen = subprocess.Popen(
                command,
                close_fds=True,
                startupinfo=startupinfo,
                **streams
            )
        except OSError as exc:
            raise os_error(exc, "cannot start the helper process") from exc
        except (TypeError, ValueError) as exc:
            raise WSpawnError("cannot start the helper process: %s" % exc, kind="badarg") from exc
    finally:
        for handle in restore:
            try:
                _winapi.set_handle_information(handle, _winapi.HANDLE_FLAG_INHERIT, 0)
            except OSError:
                pass
        for descriptor in temporary_fds:
            try:
                os.close(descriptor)
            except OSError:
                pass

    return SpawnedProcess(popen, handles)


__all__ = ["SpawnedProcess", "spawn", "WSpawnError"]

